"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8129],{18129:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-vegetarian.png\\"\\n          title=\\"채식주의자\\"\\n          author=\\"한강\\"\\n          publisher=\\"창비\\"\\n          publishedDate=\\"2007-10-30\\"\\n          isbn=\\"9788936433598\\"\\n          rating=4.5\\n          tags=\\"novel\\"\\n        />\\n</center>\\n\\n## Review\\n나에겐 다소 힘든 책이었다. 내용이 어렵다기보다는 작가의 표현과 단어 선택에서 한 인물의 힘든 감정이 잘 드러난다.  \\n과거 ```정유정``` 작가님의 <mark>28</mark>을 봤을 때와 비슷한 힘듦을 느꼈다.  \\n<br>\\n남편, 형부 그리고 언니의 시선으로 바라보는 ```영혜```에게 느끼는 감정이 모두 다르다. 막상 주인공 ```영혜```의 시점은 없다.  \\n<br>\\n이 작품 역시 여러 번 읽어야 하는 책인 것 같다.  \\n<br>\\n```한강``` 작가님의 표현과 단어 선택이 주는 몰입감과 생동감에 다른 작품 읽기가 좀 두려워진다.  \\n특히 <mark>소년이 온다</mark>는 큰맘 먹고 읽어야 할 것 같다."}')}}]);